# Column names per delimited depot (used to recognise header rows).
COLUMNS = {
    "east": ["id", "type", "shipped", "gross", "net", "status", "note"],
    "harbor": ["rec", "ref", "date", "weight", "state"],
    "lakeside": ["id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"],
    "river": ["t", "ref", "shipped", "weight", "status"],
    "west": ["id", "typ", "shipped", "weight", "status", "note"],
}
DELIM = {"east": ",", "harbor": "|", "lakeside": ",", "river": "\t", "west": ";"}
# role -> column name
ROLES = {
    "east": {"id": "id", "type": "type", "shipped": "shipped", "weight": "gross", "status": "status"},
    "harbor": {"id": "ref", "type": "rec", "shipped": "date", "weight": "weight", "status": "state"},
    "lakeside": {"id": "id", "type": "kind", "shipped": "shipped", "weight": "gross_kg", "status": "status"},
    "river": {"id": "ref", "type": "t", "shipped": "shipped", "weight": "weight", "status": "status"},
    "west": {"id": "id", "type": "typ", "shipped": "shipped", "weight": "weight", "status": "status"},
}
BASE_DATE_FORM = {"east": "YMD", "harbor": "iso", "lakeside": "iso", "river": "MM/DD/YYYY",
                  "west": "DD.MM.YYYY"}
# directive names carrying the weight unit / date form, per depot
UNIT_DIRECTIVE = {"east": "unit", "river": "weight unit", "west": "weight unit"}
DATE_DIRECTIVE = {"east": "dates", "lakeside": "dates", "river": "date format"}
FIELD_UNIT = {"lakeside": "kg"}  # unit named by the weight field itself
BASE_UNIT = "kg"
DECIMAL_COMMA = {"west"}

STATUS_CODES = {"dlv": "delivered", "dll": "delivered_late", "can": "cancelled",
                "ret": "returned", "hld": "held"}

FW_LAYOUTS = {
    # name: (length, id, type, shipped, weight, status, shipped form, weight unit, weight scale)
    "FW1": dict(length=42, id=(0, 9), type=(9, 10), shipped=(10, 17), weight=(17, 25),
