}
FW_STATUS = {"d": "delivered", "l": "delivered_late", "c": "cancelled", "r": "returned", "h": "held"}


class Rec:
    __slots__ = ("num", "kind", "status", "kg", "day")

    def __init__(self, num, kind, status=None, kg=None, day=None):
        self.num, self.kind, self.status, self.kg, self.day = num, kind, status, kg, day


# --------------------------------------------------------------------- bytes
def read_bytes(path):
    with open(path, "rb") as f:
        b = f.read()
    while b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    return b


def decode_text(b):
    if b[:3] == b"\xef\xbb\xbf":
        return b[3:].decode("utf-8", errors="replace")
    if b[:2] == b"\xff\xfe":
        return b[2:].decode("utf-16-le", errors="replace")
    if b[:2] == b"\xfe\xff":
        return b[2:].decode("utf-16-be", errors="replace")
