def to_kg(value, unit):
    return Decimal(value) * UNIT_KG[unit]


def parse_number(text, depot):
    """Return (Decimal, unit-or-None) for a weight string."""
    t = text.strip()
    m = re.fullmatch(r"([+-]?[\d.,\s']*\d|[+-]?[\d.,]*\.\d+)\s*([A-Za-z]+)?", t)
