    raise ValueError("bad date %r (form %r)" % (s, form))


# ------------------------------------------------------------ delimited text
def split_logical_lines(text):
    """Yield (is_comment, line) pairs; quoted fields can span lines."""
    lines = text.split("\n")
    cur = None
    for line in lines:
        if cur is None:
            if line.endswith("\r"):
                line = line[:-1]
            if line.strip() == "":
                continue
            if line.startswith("#"):
                yield True, line
                continue
            cur = line
        else:
            cur += "\n" + line
        if cur.count('"') % 2 == 0:
            yield False, cur
            cur = None
    if cur is not None:
        yield False, cur


def parse_delimited(depot, text):
    seq = None
    directives = {}
    header = None
    names = set(COLUMNS[depot])
    delim = DELIM[depot]
    roles = ROLES[depot]
    out = []
    for is_comment, line in split_logical_lines(text):
        if is_comment:
            m = re.match(r"#\s*([^:=]+?)\s*[:=]\s*(.*)$", line)
            if m:
                name, val = m.group(1).strip().lower(), m.group(2).strip()
