            else:
                m = re.match(r"#\s*\w+\s+export\s+seq\s*=\s*(\d+)", line)
                if m and seq is None:
                    seq = int(m.group(1))
            continue
        if delim == ",":
            try:
                fields = next(csv.reader([line]))
            except Exception:
                continue
        else:
            fields = line.split(delim)
        stripped = [f.strip() for f in fields]
        if len(stripped) >= 3 and all(f.lower() in names for f in stripped):
            header = [f.lower() for f in stripped]
            continue
        if header is None:
            continue
        col = {n: i for i, n in enumerate(header)}
        wcol = col.get(roles["weight"])
        row_unit = None
        if len(fields) == len(header) + 1 and wcol is not None:
            cand = [wcol + 1] + [i for i in range(len(fields))]
            for i in cand:
                if i < len(fields) and norm_unit(fields[i]) and fields[i].strip() != "":
                    row_unit = norm_unit(fields[i])
                    fields = fields[:i] + fields[i + 1:]
                    break
