            # a trailer or damaged row; only rows with a shipment id matter
            if len(fields) < len(header):
                fields = fields + [""] * (len(header) - len(fields))
            else:
                fields = fields[:len(header)]

        def get(role):
            i = col.get(roles[role])
            return fields[i].strip() if i is not None and i < len(fields) else ""

        num = norm_id(get("id"))
        if num is None:
            continue
        kind = norm_kind(get("type"))
        if kind == "void":
            out.append(Rec(num, kind))
            continue
        try:
