                break
        if lay is None:
            lay = FW_LAYOUTS.get(layout)
            if lay is None:
                continue
            line = line.ljust(lay["length"])
        try:
            def fld(k):
                a, b = lay[k]
                return line[a:b]
            num = norm_id(fld("id"))
            if num is None:
                continue
            kind = norm_kind(fld("type"))
            if kind == "void":
                out.append(Rec(num, kind))
                continue
            status = FW_STATUS.get(fld("status").strip().lower())
            if status is None:
                status = norm_status(fld("status"))
            day = parse_day(fld("shipped"), lay["dform"])
            kg = Decimal(int(fld("weight"))) * lay["scale"] * UNIT_KG[lay["unit"]]
