# ----------------------------------------------------------------------- xml
def parse_central(b):
    root = ET.fromstring(b)
    seq = None
    try:
        seq = int(root.attrib.get("seq", ""))
    except ValueError:
        pass
    root_unit = norm_unit(root.attrib.get("weight-unit"))
    out = []
    for s in root.iter("shipment"):
        def val(name):
            if name in s.attrib:
                return s.attrib[name]
            ch = s.find(name)
            return ch.text if ch is not None and ch.text is not None else None
        num = norm_id(s.attrib.get("id") if "id" in s.attrib else val("id"))
        if num is None:
            continue
        kind = norm_kind(s.attrib.get("type"))
        if kind == "void":
            out.append(Rec(num, kind))
            continue
        try:
            status = norm_status(val("status"))
            day = parse_day(val("shipped"), "16 Mar 2026")
            wel = s.find("weight")
            if wel is not None:
                wtext = wel.text
                unit = norm_unit(wel.attrib.get("unit"))
            else:
                wtext = s.attrib.get("weight")
                unit = norm_unit(s.attrib.get("unit"))
            w, u2 = parse_number(wtext, "central")
            unit = unit or u2 or root_unit or BASE_UNIT
            out.append(Rec(num, kind, status, to_kg(w, unit), day))
        except Exception as e:
            sys.stderr.write("warning: central: skipped %r: %s\n" % (s.attrib.get("id"), e))
    return seq, out


# --------------------------------------------------------------------- jsonl
def parse_north(text):
    seq = None
    out = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        try:
            v = json.loads(line, parse_float=Decimal, parse_int=Decimal)
        except ValueError:
            continue
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if "meta" in o and isinstance(o["meta"], dict):
                if seq is None and "seq" in o["meta"]:
                    seq = int(o["meta"]["seq"])
                continue
            num = norm_id(o.get("id"))
            if num is None:
                continue
            kind = norm_kind(o.get("kind"))
            if kind == "void":
                out.append(Rec(num, kind))
                continue
            try:
                wkey = next(k for k in o if k.startswith("weight"))
                unit = norm_unit(wkey.split("_", 1)[1]) if "_" in wkey else norm_unit(o.get("unit"))
                w = o[wkey]
                if isinstance(w, str):
                    w, u2 = parse_number(w, "north")
                    unit = unit or u2
                unit = unit or BASE_UNIT
                day = parse_day(o["shipped_at"], "iso")
                out.append(Rec(num, kind, norm_status(o.get("status")), to_kg(w, unit), day))
            except Exception as e:
                sys.stderr.write("warning: north: skipped %r: %s\n" % (o.get("id"), e))
    return seq, out


# ---------------------------------------------------------------------- main
def parse_file(depot, path):
    b = read_bytes(path)
    if depot == "central":
        return parse_central(b)
    text = decode_text(b)
    if depot == "south":
        return parse_south(text)
    if depot == "north":
        return parse_north(text)
    if depot in COLUMNS:
        return parse_delimited(depot, text)
    sys.stderr.write("warning: unknown depot %r in %s\n" % (depot, path))
    return None, []


def money(d):
    return float(d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def main(data_dir, out_file):
    files = []
    for e in sorted(os.scandir(data_dir), key=lambda e: e.name):
        if e.is_file():
            files.append((e.name.split("-", 1)[0], e.name, e.path))
    depots = {}
    for depot, name, path in files:
        try:
            seq, recs = parse_file(depot, path)
        except Exception as ex:
            sys.stderr.write("warning: cannot read %s: %s\n" % (path, ex))
            seq, recs = None, []
        depots.setdefault(depot, []).append((seq if seq is not None else -1, name, recs))

    corrections = resends = 0
    current = {}
    for depot, exports in depots.items():
        cur = {}
        for seq, name, recs in sorted(exports, key=lambda x: (x[0], x[1])):
            for r in recs:
                if r.kind == "new":
                    if r.num in cur:
                        resends += 1
                    else:
                        cur[r.num] = r
                elif r.kind == "correction":
                    cur[r.num] = r
                    corrections += 1
                else:
                    cur.pop(r.num, None)
                    corrections += 1
        current[depot] = cur

    order = {d: i for i, d in enumerate(HANDOVER_ORDER)}
    ranked = sorted(current, key=lambda d: (order.get(d, len(order)), d))
    owners = {}
    handovers = 0
    for depot in ranked:
        for num, r in current[depot].items():
            if num in owners:
                continue
            owners[num] = (depot, r)
    seen = {}
    for depot in current:
        for num in current[depot]:
            seen[num] = seen.get(num, 0) + 1
    handovers = sum(1 for n in seen.values() if n > 1)

    dep_tot = {d: [0, Decimal(0)] for d in sorted(depots)}
    mon_tot = {}
    for num, (depot, r) in owners.items():
        if r.status not in ("delivered", "delivered_late"):
            continue
        dep_tot[depot][0] += 1
        dep_tot[depot][1] += r.kg
        key = "%04d-%02d" % (r.day.year, r.day.month)
        t = mon_tot.setdefault(key, [0, Decimal(0)])
        t[0] += 1
        t[1] += r.kg

    result = {
        "depots": {d: {"shipments": t[0], "total_kg": money(t[1])} for d, t in dep_tot.items()},
        "months": {k: {"shipments": mon_tot[k][0], "total_kg": money(mon_tot[k][1])}
                   for k in sorted(mon_tot)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    os.makedirs(os.path.dirname(os.path.abspath(out_file)), exist_ok=True)
    with open(out_file, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: summarize.py DATA_DIR OUT_FILE")
    main(sys.argv[1], sys.argv[2])
